const NAME_PACK: Partial<Record<LangId, string[]>> = { en: NAME_EN, ar: NAME_AR, id: NAME_ID, tr: NAME_TR, ur: NAME_UR };

export function nameText(n: AllahName, lang: LangId): { name: string; meaning: string } {
  if (lang === "ru") return { name: n.name, meaning: n.meaning };
  const i = Number(n.id.slice(1)) - 1;
  const meaning = NAME_PACK[lang]?.[i];
  return { name: lang === "ar" || lang === "ur" ? n.arabic : n.name, meaning: meaning ?? n.meaning };
}

